<?php use VazinCMS\Security; ?><section class="title"><div><h1>کیف پول <?=Security::e($wallet['customer'])?></h1><p><?=Security::e($wallet['email'].' · '.$wallet['currency'])?></p></div><a class="button secondary" href="/admin/wallets">بازگشت</a></section><?php if($error):?><div class="alert"><?=Security::e($error)?></div><?php endif;?>
<section class="grid wallet-summary"><article class="panel"><span class="muted">موجودی فعلی</span><h2><?=Security::e($wallet['balance'].' '.$wallet['currency'])?></h2></article><article class="panel"><span class="muted">تعداد تراکنش نمایشی</span><h2><?=count($transactions)?></h2></article></section>
<section class="split"><div class="panel"><h2>اصلاح موجودی</h2><form method="post"><input type="hidden" name="_csrf" value="<?=Security::e(Security::csrf())?>"><input type="hidden" name="action" value="adjust"><label>نوع<select name="kind"><option value="credit">افزایش موجودی</option><option value="debit">کاهش موجودی</option></select></label><label>مبلغ<input name="amount" type="number" min="0.01" step="0.01" required></label><label>شناسه مرجع<input name="reference" maxlength="255"></label><label>توضیح<textarea name="description" rows="3" required></textarea></label><button>ثبت تراکنش</button></form></div><div class="panel"><h2>پرداخت فاکتور از کیف پول</h2><?php if(!$invoices):?><p class="muted">فاکتور پرداخت‌نشده‌ای با این ارز وجود ندارد.</p><?php else:?><form method="post"><input type="hidden" name="_csrf" value="<?=Security::e(Security::csrf())?>"><input type="hidden" name="action" value="pay_invoice"><label>فاکتور<select name="invoice_id" required><?php foreach($invoices as $i):$due=max(0,(float)$i['total']-(float)$i['paid_amount']);?><option value="<?=$i['id']?>"><?=Security::e($i['invoice_number'].' — '.number_format($due,2).' '.$i['currency'])?></option><?php endforeach;?></select></label><button>پرداخت کامل از کیف پول</button></form><?php endif;?></div></section>
<section class="panel stack-panel"><h2>گردش کیف پول</h2><div class="table-wrap"><table><thead><tr><th>تاریخ</th><th>نوع</th><th>مبلغ</th><th>مانده</th><th>توضیح</th><th>مرجع</th><th>ثبت‌کننده</th></tr></thead><tbody><?php foreach($transactions as $t):?><tr><td><?=Security::e($t['created_at'])?></td><td><span class="status <?=$t['type']==='credit'?'active':'pending'?>"><?=$t['type']==='credit'?'واریز':'برداشت'?></span></td><td><?=Security::e($t['amount'].' '.$t['currency'])?></td><td><?=Security::e($t['balance_after'])?></td><td><?=Security::e($t['description'])?></td><td><?=Security::e((string)$t['reference'])?></td><td><?=Security::e((string)$t['staff_name'])?></td></tr><?php endforeach;?></tbody></table></div></section>
